
import { appName } from '@/env';
import { dispatchCheckLoggedIn, dispatchCheckToken } from '@/store/main/actions';
import { readLoginError, readSupportsAuth } from '@/store/main/getters';
import { Component, Vue, Watch } from 'vue-property-decorator';


@Component
export default class Login extends Vue {
  public token: string = '';
  public appName = appName;
  public get loginError() {
    return readLoginError(this.$store);
  }
  public loading = false;

  public submit() {
    this.loading = true;
    dispatchCheckToken(this.$store, {token: this.token})
  }

  @Watch('loginError')
  public onLoginErrorChange(error: string | null) {
    if (error) {
      this.loading = false;
    }
  }
  

  private getTokenFromUrl() {
    // @ts-ignore
    return this.$router.history.current.query.token;
  }
  private async mounted() {
    await dispatchCheckLoggedIn(this.$store);
    if (!readSupportsAuth(this.$store)) {
      this.$router.replace({ path: '/main/dashboard', query: this.$route.query });
      return;
    }
    this.token = this.getTokenFromUrl();
    if (this.token) {
      this.submit();
    }
 }
}
